\newcommand{\Oct}{\operatorname{Oct}}
\newcommand{\coind}{\operatorname{coind}}
\newcommand{\Ztwo}{\mathbb{Z}_2}

\title{The Suspension Tower of Free $\mathbb{Z}_2$-Complexes\\ and an Iterated Borsuk--Ulam Obstruction}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}

\begin{abstract}
We study the combinatorial $\Ztwo$-co-index of free $\Ztwo$-simplicial complexes
under the suspension operation. Working entirely within a finite, combinatorial
model---free $\Ztwo$-complexes, equivariant simplicial maps, and the octahedral
spheres $\Oct(n) \cong S^n$---we prove that suspension raises the $\Ztwo$-co-index by
at least one, and that the $k$-fold \emph{suspension tower} $S^k(K)$ therefore raises
the co-index by at least $k$. Applied to octahedral spheres, the tower over $S^n$
realizes co-index $n+k$; we further prove that its dimension is \emph{exactly} $n+k$
via matched lower and upper bounds on maximal face cardinality. Consequently the tower
is \emph{co-index efficient}: the excess $\coind - \dim$ remains identically zero at
every level, making the tower the canonical zero-excess reference family. Finally, we
upgrade the combinatorial Borsuk--Ulam base case (no equivariant simplicial map from a
positive-dimensional sphere onto $S^0$) to an \emph{iterated obstruction}: for every
$k \ge 1$ there is no equivariant simplicial map from the $k$-fold suspension of $S^0$
back onto $S^0$. The obstruction is non-vacuous precisely because the tower genuinely
realizes co-index $k$.
\end{abstract}

\maketitle

\section{Introduction}

The Borsuk--Ulam theorem---that every continuous map $S^n \to \mathbb{R}^n$ identifies
some antipodal pair---is a fixed point of modern combinatorics. Through the work of
Lov\'asz, B\'ar\'any, and others it became the engine behind topological lower bounds
for the chromatic number, fair-division results, and Kneser-type theorems. The
organizing invariant is the $\Ztwo$-\emph{co-index} of a free $\Ztwo$-space: the
largest $n$ for which there is an equivariant map $S^n \to X$.

This paper isolates and answers, sharply, how the co-index behaves under
\emph{suspension}, the operation $S(X) = X * S^0$ that turns $S^n$ into $S^{n+1}$. We
work in a fully finite combinatorial category so that every statement is an explicit,
checkable fact about finite simplicial complexes and vertex maps. Our contributions:
\begin{enumerate}
\item \textbf{Single-step growth:} suspension raises the co-index by at least one
  (Theorem~\ref{thm:single}).
\item \textbf{Tower growth:} the $k$-fold suspension tower raises the co-index by at
  least $k$ (Theorem~\ref{thm:tower}); over $S^n$ it realizes co-index $n+k$
  (Corollary~\ref{cor:towersphere}).
\item \textbf{Exact dimension:} the tower over $S^n$ has dimension exactly $n+k$
  (Theorems~\ref{thm:dimlower}--\ref{thm:dimupper}); hence it is zero-excess.
\item \textbf{Iterated Borsuk--Ulam:} no equivariant simplicial map sends the $k$-fold
  suspension of $S^0$ onto $S^0$ for any $k \ge 1$ (Theorem~\ref{thm:iterbu}),
  non-vacuously.
\end{enumerate}

\section{The combinatorial model}

\begin{definition}[Free $\Ztwo$-complex]
Let $V$ be a type with decidable equality. A \emph{free $\Ztwo$-complex} on $V$
consists of an involutive, fixed-point-free \emph{antipodal map} $\alpha : V \to V$
(so $\alpha(\alpha v)=v$ and $\alpha v \ne v$), together with a downward-closed family
of finite \emph{faces} $s \subseteq V$ containing $\emptyset$ and closed under the
antipodal map ($s$ a face $\Rightarrow \alpha(s)$ a face).
\end{definition}

\begin{definition}[Equivariant simplicial map]
Let $K$ (on $V$), $L$ (on $W$) be free $\Ztwo$-complexes. A \emph{$\Ztwo$-simplicial
map} $f : K \to L$ is a vertex map $f : V \to W$ that is equivariant,
$f(\alpha_K v) = \alpha_L(f v)$, and face-preserving, $s$ a face of $K$ $\Rightarrow$
$f(s)$ a face of $L$. These compose and admit identities, forming a category.
\end{definition}

\begin{definition}[Octahedral $n$-sphere]
Fix $n \ge 0$. On the vertex set $\{0,\dots,n\}\times\{\mathrm{T},\mathrm{F}\}$ define
$\alpha(i,b)=(i,\lnot b)$, and declare $s$ a face iff it contains \emph{no antipodal
pair} (for no axis $i$ are both $(i,\mathrm{T})$ and $(i,\mathrm{F})$ in $s$). This is
$\Oct(n)$, the boundary complex of the $(n{+}1)$-cross-polytope, a triangulation of
$S^n$, and a free $\Ztwo$-complex.
\end{definition}

\begin{definition}[Co-index lower bound]
Write $\coind(K)\ge n$ iff there exists an equivariant simplicial map
$\Oct(n)\to K$. The identity gives $\coind(\Oct(n)) \ge n$.
\end{definition}

\section{Suspension}

\begin{definition}[Suspension]
For a free $\Ztwo$-complex $K$ on $V$, its \emph{suspension} $S(K)=K*S^0$ has vertex
set $V \sqcup \{\mathrm{north},\mathrm{south}\}$, antipodal map acting as $\alpha_K$ on
$V$ and swapping the two apexes, and faces those sets $T$ whose base part is a face of
$K$ \emph{and} which contain at most one apex.
\end{definition}

\begin{proposition}[Functoriality]\label{prop:functor}
An equivariant simplicial map $g:K\to L$ induces $S(g):S(K)\to S(L)$, acting as $g$ on
the base and the identity on apexes.
\end{proposition}
\begin{proof}[Proof sketch]
Set $S(g)=g\sqcup\mathrm{id}$. Equivariance and face preservation on the base come
from $g$; apexes map to apexes injectively, so the ``at most one apex'' condition is
preserved.
\end{proof}

\begin{proposition}[Suspending a sphere]\label{prop:suspsphere}
$S(\Oct(n)) \cong \Oct(n+1)$, realized by an explicit equivariant simplicial map
$\Oct(n+1)\to S(\Oct(n))$.
\end{proposition}
\begin{proof}[Proof sketch]
Send $(i,b)$ to the base bead $(i,b)$ when $i<n+1$ and to the apex of sign $b$ when
$i=n+1$. This identifies the last antipodal axis with the pair of poles; equivariance
and face preservation follow because ``no antipodal pair on the last axis'' becomes
``at most one apex''.
\end{proof}

\section{Suspension raises the co-index}

\begin{theorem}[Single-step growth]\label{thm:single}
If $\coind(K)\ge m$ then $\coind(S(K)) \ge m+1$.
\end{theorem}
\begin{proof}
Let $g:\Oct(m)\to K$ be equivariant. By Proposition~\ref{prop:functor},
$S(g):S(\Oct(m))\to S(K)$; by Proposition~\ref{prop:suspsphere} there is
$\Oct(m+1)\to S(\Oct(m))$. Composing yields an equivariant simplicial map
$\Oct(m+1)\to S(K)$.
\end{proof}

\section{The suspension tower}

\begin{definition}[Suspension tower]
Define $S^0(K)=K$ and $S^{k+1}(K)=S(S^k(K))$. Its vertex type is the iterated sum
$V\oplus\mathrm{Bool}^{\oplus k}$, decidable at every level.
\end{definition}

\begin{theorem}[Tower growth]\label{thm:tower}
If $\coind(K)\ge m$ then $\coind(S^k(K)) \ge m+k$ for all $k\ge 0$.
\end{theorem}
\begin{proof}
Induction on $k$: the base is the hypothesis, and the step applies
Theorem~\ref{thm:single} to the inductive certificate.
\end{proof}

\begin{corollary}[Tower over a sphere]\label{cor:towersphere}
$\coind(S^k(\Oct(n))) \ge n+k$ for all $n,k \ge 0$.
\end{corollary}

\section{Exact dimension of the tower}

The dimension is the maximal face cardinality minus one.

\begin{theorem}[Dimension lower bound]\label{thm:dimlower}
$S^k(\Oct(n))$ has a face of cardinality exactly $n+1+k$; its dimension is $\ge n+k$.
\end{theorem}
\begin{proof}
Induction on $k$. The positive orthant $\{(i,\mathrm{T}):i\le n\}$ is a face of
$\Oct(n)$ with $n+1$ vertices. Inserting one apex into the base image of a size
$n+1+k$ face yields a face of $S^{k+1}(\Oct(n))$ of size $n+2+k$.
\end{proof}

\begin{theorem}[Dimension upper bound]\label{thm:dimupper}
Every face of $S^k(\Oct(n))$ has at most $n+1+k$ vertices; its dimension is
$\le n+k$.
\end{theorem}
\begin{proof}
Induction on $k$. For $k=0$, a face of $\Oct(n)$ has at most one bead per axis, hence
$\le n+1$ vertices. For the step, split a face $T$ of $S^{k+1}(\Oct(n))$ into its base
part (a face of $S^k(\Oct(n))$, size $\le n+1+k$) and its apex part (at most one
apex). Thus $|T|\le n+2+k$.
\end{proof}

\begin{corollary}[Zero excess]\label{cor:zeroexcess}
$\coind(S^k(\Oct(n))) = \dim(S^k(\Oct(n))) = n+k$; the excess $\coind-\dim$ is
identically zero.
\end{corollary}
\begin{proof}
Corollary~\ref{cor:towersphere} gives $\coind \ge n+k$; since $\coind \le \dim$ and
Theorem~\ref{thm:dimupper} gives $\dim \le n+k$ while Theorem~\ref{thm:dimlower} gives
$\dim \ge n+k$, all three quantities coincide.
\end{proof}

\section{An iterated Borsuk--Ulam obstruction}

\begin{theorem}[Combinatorial Borsuk--Ulam, base case]\label{thm:bubase}
If there is an equivariant simplicial map $\Oct(n)\to\Oct(0)$, then $n=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Suppose $n\ge 1$ with $g:\Oct(n)\to\Oct(0)$. The target $S^0$ has two vertices (an
antipodal pair) and no face with two distinct vertices. For beads $a=(0,\mathrm{T})$,
$b=(1,\mathrm{T})$ on distinct axes, $\{a,b\}$ is a face, forcing $g(a)=g(b)$. But
$\{a,\alpha b\}$ is also a face, so $\{g(a),\alpha(g(a))\}$ would be a face of $S^0$;
this antipodal pair is not a face---a contradiction. Hence $n=0$.
\end{proof}

\begin{theorem}[Iterated Borsuk--Ulam obstruction]\label{thm:iterbu}
For every $k\ge 1$ there is no equivariant simplicial map
$S^k(\Oct(0)) \to \Oct(0)$.
\end{theorem}
\begin{proof}
Given such a $g$, compose with the tower certificate
$f:\Oct(k)\to S^k(\Oct(0))$ from Corollary~\ref{cor:towersphere} (with $n=0$) to get
an equivariant map $\Oct(k)\to\Oct(0)$. Theorem~\ref{thm:bubase} forces $k=0$,
contradicting $k\ge 1$.
\end{proof}

\begin{remark}[Non-vacuity]
By Corollary~\ref{cor:zeroexcess} the tower $S^k(\Oct(0))$ genuinely has co-index and
dimension $k$, so the obstruction concerns a real $k$-dimensional object---a discrete
shadow of the fact that $S^k$ admits no odd map to $S^0$ for $k\ge 1$.
\end{remark}

\section{Applications and future work}

The $\Ztwo$-co-index of a graph's box complex $B(G)$ underpins the Lov\'asz-type bound
$\chi(G)\ge \coind(B(G))+2$. Via Csorba's identity $B_0(G)\simeq S(B(G))$, suspension
corresponds to concrete graph operations, so control of how suspension moves the
co-index transfers to chromatic lower bounds; large excess certifies looseness of the
topological bound. The zero-excess tower is the calibration standard for this excess
programme.

Three conjectures point forward: (1) the excess sequence
$e_k=\coind(S^k(K))-\dim(S^k(K))$ is non-increasing and eventually constant; (2) for
every $d\ge 2$, $1\le c\le d$ there is $K$ with $\dim K=d$, $\coind K=c$, and
$\coind(S(K))=d+1$ (maximal single-step excess); (3) there is no equivariant
simplicial map $\Oct(m)\to\Oct(n)$ for $m>n$, i.e. $\coind(\Oct(n))=n$ exactly, and
more generally none $S^k(\Oct(m))\to\Oct(n)$ when $m+k>n$.

\section{Conclusion}

Within a finite combinatorial model we established a sharp staircase: one suspension
raises the $\Ztwo$-co-index by at least one, the $k$-fold tower by at least $k$, and
over an octahedral sphere co-index and dimension climb in lockstep to $n+k$, giving
identically zero excess. Iterating the Borsuk--Ulam base case forbids any $k$-fold
suspension of $S^0$ ($k\ge 1$) from retracting equivariantly onto $S^0$. The
suspension tower is thus the canonical zero-excess reference family, tightening the
bridge between combinatorial co-index and the topological Borsuk--Ulam obstruction.

\end{document}

