"""Demo: Brute-force verification of the iterated Borsuk-Ulam obstruction.

Builds the k-fold suspension tower over the 0-sphere and exhaustively searches
for an equivariant simplicial map back onto the 0-sphere. Confirms none exists
for k >= 1, while one exists for k = 0 (the identity)."""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, Iterable, List, Optional

Vertex = object
Face = FrozenSet[Vertex]


class Z2Complex:
    def __init__(self, vertices: Iterable[Vertex], alpha: Callable[[Vertex], Vertex],
                 is_face: Callable[[Face], bool]) -> None:
        self.vertices: List[Vertex] = list(vertices)
        self.alpha = alpha
        self.is_face = is_face

    def all_faces(self) -> List[Face]:
        out: List[Face] = []
        for r in range(len(self.vertices) + 1):
            for c in combinations(self.vertices, r):
                f = frozenset(c)
                if self.is_face(f):
                    out.append(f)
        return out


def oct_sphere(n: int) -> Z2Complex:
    verts = [(i, b) for i in range(n + 1) for b in (True, False)]
    def alpha(v: Vertex) -> Vertex:
        i, b = v  # type: ignore[misc]
        return (i, not b)
    def is_face(s: Face) -> bool:
        ax: dict = {}
        for (i, b) in s:  # type: ignore[misc]
            if i in ax and ax[i] != b:
                return False
            ax[i] = b
        return True
    return Z2Complex(verts, alpha, is_face)


def suspend(K: Z2Complex) -> Z2Complex:
    verts = [("base", v) for v in K.vertices] + [("apex", True), ("apex", False)]
    def alpha(v: Vertex) -> Vertex:
        t, x = v  # type: ignore[misc]
        return ("base", K.alpha(x)) if t == "base" else ("apex", not x)
    def is_face(s: Face) -> bool:
        base = frozenset(x for (t, x) in s if t == "base")  # type: ignore[misc]
        apex = sum(1 for (t, _x) in s if t == "apex")  # type: ignore[misc]
        return K.is_face(base) and apex <= 1
    return Z2Complex(verts, alpha, is_face)


def tower(K: Z2Complex, k: int) -> Z2Complex:
    for _ in range(k):
        K = suspend(K)
    return K


def find_equivariant_map(K: Z2Complex, L: Z2Complex) -> Optional[dict]:
    kf = K.all_faces()
    seen: set = set()
    reps: List[Vertex] = []
    for v in K.vertices:
        if v in seen:
            continue
        reps.append(v)
        seen.add(v); seen.add(K.alpha(v))
    assign: dict = {}
    def ok() -> bool:
        for f in kf:
            if not L.is_face(frozenset(assign[v] for v in f)):
                return False
        return True
    def bt(i: int) -> Optional[dict]:
        if i == len(reps):
            return dict(assign) if ok() else None
        v = reps[i]
        for w in L.vertices:
            assign[v] = w
            assign[K.alpha(v)] = L.alpha(w)
            r = bt(i + 1)
            if r is not None:
                return r
        del assign[v]; del assign[K.alpha(v)]
        return None
    return bt(0)


def main() -> None:
    L = oct_sphere(0)
    for k in range(0, 4):
        T = tower(oct_sphere(0), k)
        m = find_equivariant_map(T, L)
        print(f"k={k}: map S^{k}(S^0) -> S^0 "
              f"{'exists' if m else 'does NOT exist'}")


if __name__ == "__main__":
    main()

"""Demo: Co-index growth versus dimension growth in the suspension tower.

Tabulates, for the tower over Oct(n), the guaranteed co-index lower bound (n+k),
the exact dimension (n+k), and the resulting excess (coind - dim = 0), showing
the tower is the canonical zero-excess reference family."""
from __future__ import annotations
from typing import List, Tuple


def tower_coindex_lower(n: int, k: int) -> int:
    """coind(S^k(Oct(n))) >= n + k  (each suspension adds >= 1)."""
    return n + k


def tower_dimension(n: int, k: int) -> int:
    """dim(S^k(Oct(n))) = n + k exactly (maxface = n+1 then +1 per suspension)."""
    maxface = n + 1
    for _ in range(k):
        maxface += 1  # a suspension face contains at most one apex
    return maxface - 1


def excess(n: int, k: int) -> int:
    return tower_coindex_lower(n, k) - tower_dimension(n, k)


def table(n: int, kmax: int) -> List[Tuple[int, int, int, int]]:
    rows = []
    for k in range(kmax + 1):
        rows.append((k, tower_coindex_lower(n, k), tower_dimension(n, k), excess(n, k)))
    return rows


def main() -> None:
    for n in range(0, 3):
        print(f"Tower over Oct({n}):")
        print(f"  {'k':>3} {'coind>=':>8} {'dim':>5} {'excess':>7}")
        for k, c, d, e in table(n, 5):
            print(f"  {k:>3} {c:>8} {d:>5} {e:>7}")
        assert all(e == 0 for _, _, _, e in table(n, 5))
    print("All excess values are 0: the tower is co-index efficient.")


if __name__ == "__main__":
    main()

