from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, List, Tuple

Vertex = Tuple[int, bool]
Face = FrozenSet[Vertex]


def octahedral_faces(n: int) -> List[Face]:
    """Enumerate all faces of the octahedral n-sphere Oct(n)."""
    verts: List[Vertex] = [(i, b) for i in range(n + 1) for b in (True, False)]
    faces: List[Face] = []
    for r in range(len(verts) + 1):
        for combo in combinations(verts, r):
            axes: dict = {}
            ok = True
            for (i, b) in combo:
                if i in axes and axes[i] != b:
                    ok = False
                    break
                axes[i] = b
            if ok:
                faces.append(frozenset(combo))
    return faces


def octahedral_max_face_card(n: int) -> int:
    """Maximal face cardinality of Oct(n); equals n + 1."""
    return max((len(f) for f in octahedral_faces(n)), default=0)

