function EQUIVARIANT_MAP_EXISTS(K, L):
    reps <- one vertex per antipodal orbit of K
    assign <- empty map
    function BACKTRACK(i):
        if i = |reps|:
            return copy(assign) if all K-faces map to L-faces else None
        v <- reps[i]
        for w in vertices(L):
            assign[v] <- w; assign[alpha_K v] <- alpha_L w
            r <- BACKTRACK(i+1)
            if r != None: return r
        unset assign[v], assign[alpha_K v]
        return None
    return BACKTRACK(0)
